import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Eye, EyeOff, Mail, Lock } from 'lucide-react';
import { login as apiLogin } from '../services/api';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

export default function LoginPage() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await apiLogin(form);
      login(res.data.token, res.data.user);
      toast.success('Bienvenue !');
      navigate('/dashboard');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Identifiants incorrects');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-gradient-to-br from-green-800 via-green-900 to-slate-900">
      {/* Left decorative panel */}
      <div className="hidden lg:flex flex-1 flex-col items-center justify-center p-12 relative overflow-hidden">
        <div className="absolute inset-0 opacity-10">
          {[...Array(6)].map((_, i) => (
            <div key={i} className="absolute rounded-full border border-white/30"
              style={{ width: `${(i+1)*120}px`, height: `${(i+1)*120}px`,
                top: '50%', left: '50%', transform: 'translate(-50%, -50%)' }} />
          ))}
        </div>
        <div className="relative text-center">
          <div className="w-24 h-24 bg-white rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-2xl">
            <span className="text-green-800 font-display font-bold text-2xl">OCP</span>
          </div>
          <h1 className="text-white font-display text-4xl font-bold mb-4">Gestion du Stock</h1>
          <p className="text-green-200 text-lg max-w-xs leading-relaxed">
            Plateforme de gestion des produits électriques — OCP Benguérir
          </p>
          <div className="mt-12 grid grid-cols-3 gap-4 text-center">
            {[['Articles', 'Gérez votre inventaire'], ['Transferts', 'Tracez les mouvements'], ['Alertes', 'Stock en temps réel']].map(([t, s]) => (
              <div key={t} className="bg-white/10 rounded-2xl p-4">
                <p className="text-white font-semibold">{t}</p>
                <p className="text-green-300 text-xs mt-1">{s}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Right login form */}
      <div className="w-full lg:w-[440px] flex items-center justify-center p-8 bg-white">
        <div className="w-full max-w-sm">
          <div className="lg:hidden mb-8 text-center">
            <div className="w-16 h-16 bg-green-800 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <span className="text-white font-display font-bold text-xl">OCP</span>
            </div>
          </div>
          <h2 className="font-display text-2xl font-bold text-gray-900 mb-1">Bienvenue !</h2>
          <p className="text-gray-500 text-sm mb-8">Connectez-vous à votre compte</p>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <label className="label">Adresse e-mail</label>
              <div className="relative">
                <Mail size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input type="email" required placeholder="votre@email.com"
                  value={form.email} onChange={e => setForm({...form, email: e.target.value})}
                  className="input-field pl-9" />
              </div>
            </div>
            <div>
              <label className="label">Mot de passe</label>
              <div className="relative">
                <Lock size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input type={showPass ? 'text' : 'password'} required placeholder="••••••••"
                  value={form.password} onChange={e => setForm({...form, password: e.target.value})}
                  className="input-field pl-9 pr-9" />
                <button type="button" onClick={() => setShowPass(!showPass)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                  {showPass ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </div>
            <button type="submit" disabled={loading}
              className="w-full bg-green-700 hover:bg-green-800 text-white py-3 rounded-xl font-semibold transition-all duration-200 shadow-md disabled:opacity-60">
              {loading ? 'Connexion...' : 'Se connecter'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}
